(458, 'zhCN', 263287651, '闪避敌人近战攻击的几率，最多{1}%。“闪避”和“威慑”技能可以超过上限。'),
(459, 'zhCN', 4225567408, '20点护甲使受到的伤害降低16%，100点护甲降低43%，300点护甲降低60%，此为上限。超过300的每点护甲提供+0.5%最大生命值。'),
(460, 'zhCN', 81131219, '吸收最多相当于最大生命值一定比例的伤害。{1}内未受到伤害后重新充满。所有护盾合计最多吸收相当于最大生命值50%的伤害，拥有重装碾压时为100%。'),
(461, 'zhCN', 3393323265, '每点使你的命中有1%几率恢复1%最大生命值，每点每秒最多恢复0.03%最大生命值。召唤物的命中不计入。'),
(462, 'zhCN', 104310022, '每点每秒恢复1%最大生命值。治疗削减效果会使其降低。'),
(463, 'zhCN', 942085730, '提高升级、卡片、雕文和魔网选项的稀有度。每点使精英掉落宝箱的几率+0.1%，进化几率+0.1%。'),
(464, 'zhCN', 3783001629, '基础6码，每点+1%，最多30码。暗月奖券和雕文始终需要在3码内才能拾取。'),
(465, 'zhCN', 2258363231, '每点+1%，最多{1}%。短暂的加速效果可以超过此上限。'),
(466, 'zhCN', 1521925118, '获得更多金币。不影响勇气点数和暗月奖券。'),
(467, 'zhCN', 917853565, '获得更多经验值。'),
(468, 'zhCN', 3055849177, '在你首次通关普通难度之前，每次以死亡告终的远征都会使你获得+{1}力量，并使受到的伤害降低{1}%，最多叠加{2}层。'),
(469, 'zhCN', 307053978, '来自装备、卡片、雕文、被动技能、天赋、训练和魔网的属性会相加。上限作用于总值。'),
(470, 'zhCN', 3631810566, '致命一击几率没有上限。'),
(471, 'zhCN', 2349403873, '天赋的伤害加成计入力量。法术等级、猎人印记、被审判、关键词收益和终极天赋与其相乘。'),
(472, 'zhCN', 4204251650, '易伤和破甲与其他所有加成相乘。'),
(473, 'zhCN', 558023680, '被动技能的每一级和每多一张相同的卡片，效果为前一个的85%，但不低于10%。数量不会递减，休憩也没有下限。'),
(474, 'zhCN', 4164367766, '两件特效相同的饰品，其特效不会叠加。'),
(475, 'zhCN', 655707791, '冷却时间'),
(476, 'zhCN', 3689449152, '受急速缩短，其中包括法术自身的急速强化。最低0.2秒。范围内没有目标的法术会等待，而不是进入冷却。'),
(477, 'zhCN', 170364688, '等级'),
(478, 'zhCN', 1453549581, '普通+{1}%伤害，优秀+{2}%，精良+{3}%并获得1项强化，史诗+{4}%并获得2项强化。没有伤害的法术改为获得强化。超过20级后，每级增加的伤害逐渐减少：到40级时为一半，到80级时为四分之一。'),
(479, 'zhCN', 2211360201, '双重打击、回响和目标数强化只会来自史诗等级。'),
(480, 'zhCN', 2261358038, '进化从10级起可能出现，拥有预感时会更早出现，并保留你的等级、伤害和强化。'),
(481, 'zhCN', 260640014, '法术命中的伤害会上下浮动7%，宠物攻击浮动10%。持续伤害不会浮动。'),
(482, 'zhCN', 3860406243, '你初始拥有3个法术槽位和3个被动技能槽位。塞格出售更多槽位，最多5个法术和6个被动技能。'),
(483, 'zhCN', 973509743, '基础生命值'),
(484, 'zhCN', 2186280488, '普通难度下与该区域等级相同的普通敌人的生命值。它不会随难度、楼层、精英或首领而提高。'),
(485, 'zhCN', 4059356796, '燃烧、流血、中毒、腐朽和月火术：每层每跳造成基础生命值{1}%的伤害，持续{2}，最多{3}层。'),
(486, 'zhCN', 2490125042, '痛苦'),
(487, 'zhCN', 2555119882, '每层每跳造成基础生命值{1}%的伤害，持续{2}，并在8跳内逐渐增强至3倍。目标死亡时不会蔓延。'),
(488, 'zhCN', 1318368395, '每跳间隔1秒，急速可缩短该间隔。'),
(489, 'zhCN', 3548323307, '只有拥有相应天赋时，持续伤害才能造成致命一击，且致命一击的伤害加成只有通常的一半。'),
(490, 'zhCN', 741499879, '每叠加新的一层，都会刷新该敌人身上的所有层数。'),
(491, 'zhCN', 734972660, '力量在叠加层数或层数结束时计入。易伤则在每跳时计入。'),
(492, 'zhCN', 1580129295, '拥有2层或以上效果的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。'),
(493, 'zhCN', 3525893091, '首领每层受到的伤害相同，只是占其生命值的比例更小。'),
(494, 'zhCN', 1127040022, '每跳伤害可以触发吸血，但不会触发卡片或饰品。'),
(495, 'zhCN', 3987338015, '冰寒'),
(496, 'zhCN', 1950415089, '每层减速{1}%，最多{2}层。达到{2}层时，敌人会被冻结。'),
(497, 'zhCN', 1668424211, '冻结'),
(498, 'zhCN', 3378765346, '普通敌人被定身{1}；精英和首领仍可移动，但视为冻结。你的冰霜法术对冻结的敌人必定造成致命一击，且你对其造成的致命一击获得+50%致命一击伤害。'),
(499, 'zhCN', 2272013587, '静电'),
(500, 'zhCN', 137940027, '达到{1}层时，闪电会打击该敌人及其6码内最多3个敌人，造成基础生命值{2}%的伤害，受力量加成。可以造成致命一击。'),
(501, 'zhCN', 4043173200, '猎人印记'),
(502, 'zhCN', 2304706102, '被标记的敌人受到你和你的召唤物造成的伤害提高{1}%，施加标记的法术的等级和标记强化可将其最多提高至30%。天赋效果额外叠加。目标死亡时，标记会转移到10码内最近的2个未被标记的敌人身上。'),
(503, 'zhCN', 2243584068, '被审判'),
(504, 'zhCN', 3594214211, '被十字军审判击中的敌人受到你造成的伤害提高20%，持续6秒。'),
(505, 'zhCN', 3824701143, '眩晕'),
(506, 'zhCN', 1088335120, '减速{1}%，持续{2}。只有效果最强的减速生效。'),
(507, 'zhCN', 3445146729, '易伤'),
(508, 'zhCN', 2315643487, '火焰易伤每层使受到的伤害提高{1}%，暗影易伤{2}%，自然易伤{3}%，破甲（物理）{4}%，最多5层。'),
(509, 'zhCN', 630089074, '昏迷最多持续2秒，之后该敌人在6秒内无法再被昏迷。首领和小首领无法被昏迷。'),
(510, 'zhCN', 1742125669, '定身只对普通敌人有效，最多持续2秒，之后免疫6秒。冻结与其共用此计时。'),
(511, 'zhCN', 3685543467, '击退只对普通敌人有效，之后免疫6秒。牵引只对普通敌人有效，之后免疫3秒。'),
(512, 'zhCN', 1913320721, '恐惧和魅惑对精英和首领无效。'),
(513, 'zhCN', 1084277140, '召唤物继承你的力量、致命一击几率和致命一击伤害、急速以及移动速度。它们永远不会死亡，敌人也会无视它们。'),
(514, 'zhCN', 3620996735, '召唤物不继承你的范围。它们的命中不会触发吸血、饰品或命中触发的卡片，但它们的击杀会计入。'),
(515, 'zhCN', 2847346015, '召唤物的每次命中都会施加其所属法术的关键词。'),
(516, 'zhCN', 2476191643, '数量可增加宠物、元素、树人、图腾和狼。'),
(517, 'zhCN', 4148629273, '会自行消失的召唤物（如毒蛇、野兽、兽群奔腾、灵魂之群的狼和术士的恶魔）受持续时间加成，存在时间更长。'),
(518, 'zhCN', 3861156180, '饰品'),
(519, 'zhCN', 371619343, '施放法术时有5%几率触发，每个冷却周期最多一次。伤害类饰品按该法术下一次命中伤害的一定比例造成伤害，数量越多伤害越高，并且可以造成致命一击。范围不影响它们。'),
(520, 'zhCN', 678936335, '火焰爆发、暗影爆发、闪电链和死亡射线在施放法术时判定，并在该法术的下一次命中时触发。'),
(521, 'zhCN', 1362305071, '触发效果永远不会触发其他饰品或卡片。它们的命中可以触发吸血。'),
(522, 'zhCN', 2657233617, '雕文伤害（风暴、陨石、影之哀伤）随基础生命值、远征时长和力量提高，与难度无关。风暴必定造成致命一击。'),
(523, 'zhCN', 2585744752, '装备提供其所列属性以及套装加成。'),
(524, 'zhCN', 3931913784, '史诗阶级'),
(525, 'zhCN', 1551469000, '力量、最大生命值和护甲每阶提高12%，按复利叠加，因此T20约为T1的8.6倍。其他属性保持不变。'),
(526, 'zhCN', 2962549461, '饰品的特效不随阶级提高，但其属性会提高。'),
(527, 'zhCN', 3952381199, '废料'),
(528, 'zhCN', 811652459, '史诗远征中每件未提取的物品都会提供废料，阶级越高、额外属性越多，提供的越多。史诗精英也会掉落少量废料。史诗军需官可以用废料将你找到的装备提升1阶，最高T10，若你的最高史诗楼层更高，则以其为上限。支付金币后，他可以为每件物品重选一项额外属性。'),
(529, 'zhCN', 2888059930, '你受到的伤害会依次经过闪避、伤害减免、护甲和护盾的削减。'),
(530, 'zhCN', 3989887728, '冲刺会使你在0.25秒内免疫伤害。'),
(531, 'zhCN', 3911887352, '治疗球恢复20%最大生命值。每次升级恢复5%。'),
(532, 'zhCN', 1454284447, '死疽、首领造成的创伤和诅咒之地会降低受到的治疗效果，最多降低100%。'),
(533, 'zhCN', 3227107177, '复活'),
(534, 'zhCN', 1940049843, '你死亡时，首先由圣盾术雕文救你，其次是第二次机会，最后是灵魂石。复活会恢复你的生命值，为你施加护盾，并消灭15码内的普通敌人。'),
(535, 'zhCN', 1823495048, '迅捷'),
(536, 'zhCN', 4290024239, '爆炸'),
(537, 'zhCN', 3723519354, '死疽'),
(538, 'zhCN', 3889003145, '吸血'),
(539, 'zhCN', 3475116892, '激励'),
(540, 'zhCN', 1474812565, '血色'),
(541, 'zhCN', 826353542, '壁垒'),
