(545, 'zhCN', 2338737624, '火山'),
(546, 'zhCN', 1591841967, '移动速度提高{1}。'),
(547, 'zhCN', 3995168076, '当你靠近它时，它的周围每{1}就会爆发一次火焰。爆发前会先出现红圈预警。'),
(548, 'zhCN', 3626225075, '它的每次攻击都会降低你受到的治疗效果，且效果可以叠加。远离它即可清除该效果。'),
(549, 'zhCN', 2461167972, '按其造成伤害的{1}恢复自身生命值。'),
(550, 'zhCN', 4018992333, '它死亡时，附近敌人的生命值和伤害提高{1}。'),
(551, 'zhCN', 946213586, '它死亡时会留下一滩血池，治疗站在其中的敌人。'),
(552, 'zhCN', 2233074248, '为自身施加相当于其生命值{1}的护盾，旧护盾破碎或消失{2}后会获得新的护盾。'),
(553, 'zhCN', 2012789802, '生命值提高{1}。'),
(554, 'zhCN', 3516149494, '攻击速度提高{1}。'),
(555, 'zhCN', 536454486, '生命值低于{2}时，造成的伤害提高{1}。'),
(556, 'zhCN', 517712354, '你的脚下会不时爆发火焰。爆发前会先出现红圈预警。'),
