INSERT INTO `bonk_card_locale` (`id`, `locale`, `name`, `description`) VALUES
(1, 'zhCN', '特效治疗石', '生命值低于35%时，恢复35%最大生命值。冷却时间60秒。'),
(2, 'zhCN', '巨魔之血药水', '每秒恢复0.4%生命值。'),
(3, 'zhCN', '生命石', '最大生命值提高13.5%。每秒恢复0.2%生命值。'),
(4, 'zhCN', '迪格的奇美洛克排骨', '最大生命值提高16%。'),
(5, 'zhCN', '厚符文布绷带', '在4秒内未受到攻击后，每秒恢复1.35%生命值。'),
(6, 'zhCN', '基础营火', '原地站立1秒后，每秒恢复1.35%生命值。'),
(7, 'zhCN', '硬肉干', '火鸡腿的掉落几率提高15%，恢复效果提高30%。'),
(8, 'zhCN', '暗月卡片：英雄', '你的致命一击有20%几率为你恢复1%最大生命值，每秒最多0.8%。'),
(9, 'zhCN', '生命宝石', '溢出满生命值的治疗会转化为护盾，最多可吸收相当于20%最大生命值的伤害。每秒恢复0.25%生命值。'),
(10, 'zhCN', '埃雷萨拉斯皇家徽记', '护甲提高8点。'),
(11, 'zhCN', '力反馈盾牌', '获得一层护盾，可吸收相当于11%最大生命值的伤害。护盾破碎时，烈焰灼烧8码内的敌人。'),
(12, 'zhCN', '尖刺颈饰', '敌人击中你时，荆棘会打击8码内的所有敌人，造成相当于普通难度下普通敌人生命值40%的伤害。每0.5秒至多触发一次。'),
(13, 'zhCN', '联盟徽记', '你被击中后的0.5秒内不会受到伤害。冷却时间8秒。'),
(14, 'zhCN', '迅捷药水', '生命值降至50%以下时，移动速度提高50%，持续4秒。冷却时间20秒。'),
(15, 'zhCN', '灵魂石', '当你将要死亡时，改为以40%生命值复活。仅生效一次。'),
(16, 'zhCN', '拉格纳罗斯之手', '你的法术有5%几率对6码内的敌人造成相当于该法术伤害80%的火焰伤害。'),
(17, 'zhCN', '铁敌', '你的法术有6%几率施放两次。'),
(107, 'zhCN', '苍穹击碎者', '你的法术有6%几率施放两次。'),
(18, 'zhCN', '暗月卡片：漩涡', '你的法术有8%几率以闪电打击3个敌人，造成相当于该法术伤害70%的伤害。'),
(19, 'zhCN', '侏儒死亡射线', '你的法术有4%几率使该次施放的力量提高400%。'),
(20, 'zhCN', '嗜血胸针', '每击杀40个敌人，力量提高1%，最多提高6.5%。'),
(21, 'zhCN', '赞达拉英雄护符', '每30秒获得25%力量，持续10秒。'),
(22, 'zhCN', '黑手饰物', '致命一击几率提高4%。'),
(23, 'zhCN', '蜘蛛之吻', '急速提高7%。'),
(24, 'zhCN', '勇士印记', '对精英、小首领和首领造成的伤害提高16%，且它们对你造成的伤害降低5%。'),
(25, 'zhCN', '大地打击', '力量提高5.5%，致命一击几率提高2.7%。'),
(26, 'zhCN', '肥地精钱袋', '勇气点数提高20%。'),
(27, 'zhCN', '暗月卡片：洞察', '经验值提高13%。'),
(28, 'zhCN', '侏儒磁铁', '每180秒，将所有经验球和货币吸到你身边。'),
(29, 'zhCN', '奥金万能钥匙', '开启宝箱时有11%几率免费。'),
(31, 'zhCN', '暗月卡片：升腾', '你下次升级时，会为一个等级达到10级或以上的法术提供进化选项。提供一次后即消耗。'),
(32, 'zhCN', '龙牙饰物', '致命一击伤害提高12%。'),
(33, 'zhCN', '莫阿姆之眼', '范围提高6%。'),
(34, 'zhCN', '偏移披风', '闪避几率提高3%。'),
(35, 'zhCN', '暗月卡片：蓝龙', '你的法术有10%几率使你获得25%急速，持续6秒。冷却时间20秒。'),
(36, 'zhCN', '毒性图腾', '持续伤害提高15%。'),
(37, 'zhCN', '优越护符', '每持续一秒未被击中，力量提高1%，最多提高20%。'),
(101, 'zhCN', '雷霆之怒，逐风者的祝福之剑', '你的法术有6%几率施放闪电链，打击5个敌人，造成相当于该法术伤害150%的伤害。'),
(102, 'zhCN', '堕落的灰烬使者', '你的法术有5%几率对8码内的敌人造成相当于该法术伤害200%的暗影伤害，并为你恢复相当于该伤害10%的生命值。'),
(103, 'zhCN', '萨弗拉斯，炎魔拉格纳罗斯之手', '你的法术有6%几率对8码内的敌人造成相当于该法术伤害200%的火焰伤害。'),
(104, 'zhCN', '伦鲁迪洛尔，上古守护者的长弓', '你的法术有10%几率施放两次。'),
(105, 'zhCN', '埃提耶什，守护者的传说之杖', '数量提高1，范围提高15%。'),
(106, 'zhCN', '陨落之王', '你的致命一击有50%几率为你恢复1%最大生命值，每秒最多3%。'),
(108, 'zhCN', '萨弗拉斯之眼', '对精英、小首领和首领造成的伤害提高25%。'),
(151, 'zhCN', '囤积者雕文', '拾取范围提高60%。强化效果的持续时间加倍。'),
(153, 'zhCN', '风怒雕文', '你的法术有30%几率施放两次。');
DELETE FROM `bonk_glyph_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_glyph_locale` (`id`, `locale`, `name`, `description`, `drawback`) VALUES
(2, 'zhCN', '囤积者雕文', '拾取范围提高60%。强化效果的持续时间加倍。', ''),
(5, 'zhCN', '喘息雕文', '当30码内有一个精英、小首领或首领死亡时，为你恢复30%最大生命值。', ''),
(6, 'zhCN', '魔网雕文', '占领魔网的速度加倍。魔网提供的可选祝福由3个增至4个。', ''),
(7, 'zhCN', '风怒雕文', '你的法术有30%几率施放两次。', ''),
(8, 'zhCN', '嗜血雕文', '每击杀50个敌人，获得40%急速，持续8秒。', ''),
(11, 'zhCN', '圣盾术雕文', '受到致命伤害时，改为将你的生命值恢复全满。每次远征限一次，史诗难度下改为每5层一次。', ''),
(12, 'zhCN', '灵魂收割雕文', '每击杀50个敌人，你造成的伤害提高至三倍，持续2秒。', ''),
(13, 'zhCN', '报复雕文', '你每缺少2%生命值，力量就提高1%。', ''),
(15, 'zhCN', '赌徒雕文', '升级时提供的法术等级、宝箱中的卡片以及雕文选项的稀有度提高1级。', '升级时只提供2个选项。'),
(16, 'zhCN', '逐风者雕文', '每3秒，闪电会打击最多5个附近敌人，造成相当于普通难度下普通敌人生命值60%的伤害。必定造成致命一击。', ''),
(17, 'zhCN', '拉格纳罗斯雕文', '每6秒，一颗陨石砸向附近最大的敌群。', ''),
(18, 'zhCN', '眩目神速雕文', '冲刺充能次数增加1次。冲刺的冷却时间缩短30%。', ''),
(19, 'zhCN', '预知雕文', '每层额外获得2次重选机会。', ''),
(20, 'zhCN', '寻宝者雕文', '每2分钟，你附近会出现一个宝箱。', ''),
(21, 'zhCN', '拾荒者雕文', '你击杀的精英会掉落一个强化效果。', ''),
(22, 'zhCN', '天才雕文', '你的起手法术初始等级提高2级，造成的伤害提高25%。', ''),
(23, 'zhCN', '野心雕文', '每当小首领出现时，都会额外多出现1个。小首领给予双倍奖励。', '小首领造成的伤害提高25%。'),
(24, 'zhCN', '狩猎雕文', '精英数量加倍，每个精英给予三倍经验值。', '精英更多，危险也更多。'),
(25, 'zhCN', '破釜沉舟雕文', '生命值低于50%时，急速提高40%，移动速度提高20%。', ''),
(27, 'zhCN', '游牧者雕文', '移动时力量提高25%。', '受到生命伤害时，该效果反转为力量降低25%，持续5秒。被护盾吸收的伤害不计入。'),
(28, 'zhCN', '占卜雕文', '升级时额外提供1个选项。', ''),
(29, 'zhCN', '冰霜新星雕文', '敌人击中你时，冻结10码内的普通敌人，持续2秒。冷却时间15秒。', ''),
(30, 'zhCN', '消失雕文', '冲刺后，你在1秒内免疫伤害，且你的下一个法术必定造成致命一击。', ''),
(31, 'zhCN', '尸体爆炸雕文', '你击杀的敌人有15%几率发生爆炸，对6码内的敌人造成相当于其生命值40%的伤害。', ''),
(32, 'zhCN', '斩杀雕文', '生命值低于15%的普通敌人会立即死亡。生命值低于30%的精英、小首领和首领受到的伤害提高25%。', ''),
(33, 'zhCN', '顺劈斩雕文', '最后一击的溢出伤害会打击10码内最近的敌人。', ''),
(34, 'zhCN', '多重射击雕文', '你的法术额外射出1发箭矢。', '你的法术造成的伤害降低15%。'),
(35, 'zhCN', '回响雕文', '选择法术等级时，有25%几率额外提升1级。', ''),
(36, 'zhCN', '点燃雕文', '致命一击会施加2层燃烧。', ''),
(37, 'zhCN', '灵魂虹吸雕文', '每击杀500个敌人，力量提高1%。', ''),
(38, 'zhCN', '影之哀伤雕文', '每击杀50个敌人，你收集的灵魂会打击20码内的所有敌人，造成相当于普通难度下普通敌人生命值3倍的伤害。', ''),
(39, 'zhCN', '亡者复生雕文', '你击杀的精英会化为骷髅复生，为你而战20秒。最多同时存在5个。', '');
DELETE FROM `bonk_hidden_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_hidden_locale` (`id`, `locale`, `name`, `yell`, `found_text`) VALUES
(1, 'zhCN', '霍格', '啊啊啊……新鲜的肉！', '那片灌木丛里藏着个大家伙……是霍格！'),
(2, 'zhCN', '老瞎眼', '呣咕噜噜噜咕噜咕噜！', '一处鱼人营地！老瞎眼和他的手下从浪花中冲了出来！');
DELETE FROM `bonk_item_set_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_item_set_locale` (`id`, `locale`, `name`) VALUES
(5, 'zhCN', '史诗不屈战甲'),
(6, 'zhCN', '史诗屠杀华服');
DELETE FROM `bonk_item_set_bonus_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_item_set_bonus_locale` (`set_id`, `pieces`, `locale`, `description`) VALUES
(5, 2, 'zhCN', '最大生命值提高22.5%。'),
(5, 4, 'zhCN', '护甲提高5.6点。每秒恢复2.25%生命值。'),
(6, 2, 'zhCN', '急速提高18%。'),
(6, 4, 'zhCN', '力量提高33.75%，且你的攻击有6.75%几率为你恢复1%最大生命值。');
DELETE FROM `bonk_keyword_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_keyword_locale` (`id`, `locale`, `name`, `description`) VALUES
(1, 'zhCN', '冰寒', '每层使敌人减速3%，最多30%。叠至10层时敌人被冻结。尚不能被冻结的敌人会停留在10层。每层新叠加都会将冰寒的持续时间刷新为4秒。'),
(2, 'zhCN', '冻结', '普通敌人被原地冻结2秒。精英和首领仍可移动，但在2秒内视同被冻结。碎裂：你的冰霜法术必定对被冻结的敌人造成致命一击，且对被冻结敌人的每次致命一击额外造成50%的伤害。冻结结束后，该敌人在6秒内无法再次被冻结。'),
(3, 'zhCN', '燃烧', '每层每跳造成火焰伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。燃烧中的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。'),
(4, 'zhCN', '流血', '每层每跳造成物理伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。流血中的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。'),
(5, 'zhCN', '中毒', '每层每跳造成自然伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。中毒的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。'),
(6, 'zhCN', '火焰易伤', '每层使其受到的火焰伤害提高3%。最多叠加5次。'),
(7, 'zhCN', '破甲', '每层使其受到的物理伤害提高4%。最多叠加5次。'),
(8, 'zhCN', '暗影易伤', '每层使其受到的暗影伤害提高3%。最多叠加5次。'),
(9, 'zhCN', '猎人印记', '被标记的敌人受到你和你的召唤物造成的伤害提高15%，施加标记的法术等级和标记强化最多可将其提高至30%。天赋效果在此基础上另行叠加。被标记的敌人死亡时，标记会转移至10码内最近的2个未被标记的敌人。'),
(10, 'zhCN', '眩晕', '使敌人减速30%，持续4秒。'),
(11, 'zhCN', '静电', '最多叠加5次。叠至5层时，闪电会击中该敌人，对其及6码内最多3个敌人造成自然伤害，随后层数重置。'),
(12, 'zhCN', '自然易伤', '每层使其受到的自然伤害提高4%。最多叠加5次。'),
(13, 'zhCN', '腐朽', '每层每跳造成暗影伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。带有腐朽的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。'),
(14, 'zhCN', '痛苦', '每层每跳造成暗影伤害。每层在敌人身上每停留一跳，伤害就会增加其初始伤害的四分之一，8跳后最多增至三倍。每个敌人身上只能存在一个诅咒。'),
(15, 'zhCN', '月火术', '每层每跳造成奥术伤害。每叠加新的一层，都会将所有层数的持续时间刷新为完整时长，最多叠加30层。中了月火术的敌人死亡时，其一半的层数会蔓延至8码内最近的2个敌人。');
DELETE FROM `bonk_map_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_map_locale` (`id`, `locale`, `name`, `summary`, `description`) VALUES
(1, 'zhCN', '西部荒野', '迪菲亚暴徒、豺狼人、鱼人', '被迪菲亚兄弟会占据的农田。艾德温·范克里夫、基尔尼格或斯尼德的伐木机坐镇本层。'),
(2, 'zhCN', '熔火之心', '火焰元素、熔火恶犬、熔火巨人', '黑石山燃烧的心脏。玛格曼达、古雷曼格或迦顿男爵坐镇本层，加尔、鲁西弗隆和基赫纳斯紧随其后。'),
(3, 'zhCN', '贫瘠之地', '野猪人、半人马、土狼', '遍布钢鬃和科卡尔劫掠者的无尽干旱平原。卡尔加·刺肋、暴怒的阿迦赛罗斯或吞噬者穆坦努斯坐镇本层。'),
(4, 'zhCN', '暮色森林', '亡灵、狼人、食人魔', '亡者横行的黑暗森林。缝合怪、摩本特·费尔或伊莉莎坐镇本层。'),
(5, 'zhCN', '祖尔格拉布', '古拉巴什巨魔、蝙蝠、猛虎', '古拉巴什的神庙之城。哈卡、高阶祭司塞卡尔或血领主曼多基尔坐镇本层，金度、温诺希斯和玛尔里紧随其后。'),
(6, 'zhCN', '安其拉废墟', '异种虫群、其拉人、阿努比萨斯', '安其拉残破的大门。无疤者奥斯里安或卡苏姆男爵坐镇本层。'),
(7, 'zhCN', '塔纳利斯', '土狼、食人魔、废土流浪者强盗', '祖尔法拉克周围烈日炙烤的沙丘。加兹瑞拉或乌克兹·沙顶坐镇本层。'),
(8, 'zhCN', '安戈洛环形山', '魔暴龙、迅猛龙、软泥怪', '巨兽统治的原始环形山。暴龙之王摩什或格里什皇后坐镇本层。'),
(9, 'zhCN', '荆棘谷', '丛林巨魔、猛虎、猩猩', '遍布血顶和劈颅巨魔的茂密丛林。莫什奥格领主或甘祖拉恩坐镇本层。'),
(10, 'zhCN', '凄凉之地', '半人马、蝎子、萨特', '半人马部族彼此征战的荒凉大地。瑟莱德丝公主、被诅咒的塞雷布拉斯或洛特格里普坐镇本层。'),
(11, 'zhCN', '荒芜之地', '穴居人、黑铁矮人、雏龙', '奥达曼上方焦灼的峡谷。阿扎达斯、古代的石头看守者或黑曜石哨兵坐镇本层。'),
(12, 'zhCN', '阿拉希高地', '食人魔、枯木巨魔、辛迪加', '被食人魔和亡命之徒占据的连绵高地。弗兹鲁克或纳兹加克王子坐镇本层。'),
(13, 'zhCN', '悲伤沼泽', '鳄鱼、失落者、阿塔莱', '环绕阿塔哈卡神庙的沉陷沼泽。哈卡的化身、预言者迦玛兰或摩弗拉斯坐镇本层。'),
(14, 'zhCN', '燃烧平原', '黑石兽人、黑龙人', '黑石塔下的灰烬与烈焰。索瑞森大帝和达基萨斯将军分别坐镇各层。'),
(15, 'zhCN', '东瘟疫之地', '天灾、憎恶、瘟疫犬', '斯坦索姆城下的瘟疫中心。瑞文戴尔男爵和巴纳扎尔分别坐镇各层。'),
(16, 'zhCN', '西瘟疫之地', '血色十字军、食尸鬼、瘟疫野兽', '通灵学院与血色十字军营地之间的田野。黑暗院长加丁、詹迪斯·巴罗夫或瑟尔林·卡斯迪诺夫教授坐镇本层。'),
(17, 'zhCN', '菲拉斯', '豺狼人、食人魔、厄运之槌', '厄运之槌周围的古老森林。戈多克大王和托塞德林王子分别坐镇各层。'),
(18, 'zhCN', '灼热峡谷', '黑铁矮人、魔像、熔岩蜘蛛', '黑石山脚下熔融的矿渣坑。雷德·黑手和比斯巨兽分别坐镇各层。'),
(19, 'zhCN', '费伍德森林', '萨特、恶魔、碧火', '恶魔横行的腐化森林。卡扎克和克罗苏斯分别坐镇各层。'),
(20, 'zhCN', '丹莫罗', '穴居人、霜鬃巨魔、诺莫瑞根', '诺莫瑞根之下冰流湖的冰封湖岸。穴居人和巨魔先行，麦克尼尔·瑟玛普拉格或黑铁大使及其机器随后登场。');
