(110214, 'zhCN', '豹之迅捷', '闪避几率提高2%。'),
(10104, 'zhCN', '锯齿利刃', '你的流血造成的伤害提高12%。'),
(110204, 'zhCN', '狂血', '你的流血造成的伤害提高12%。'),
(10105, 'zhCN', '强化致死打击', '致死打击的伤害随目标身上的每层流血提高1%。'),
(10106, 'zhCN', '狂血', '顺劈斩会对其命中的所有敌人施加流血。不能与猝死同时学习。'),
(10107, 'zhCN', '猝死', '致死打击击杀敌人时，其冷却时间会重置。不能与狂血同时学习。'),
(10108, 'zhCN', '穿刺', '你的致命一击造成的伤害提高10%。'),
(10111, 'zhCN', '战术掌握', '你的致命一击造成的伤害提高10%。'),
(10223, 'zhCN', '精确', '你的致命一击造成的伤害提高10%。'),
(10312, 'zhCN', '挑衅', '你的致命一击造成的伤害提高10%。'),
