(5, 'zhCN', '再思', '每次远征额外获得1次重选机会。'),
(6, 'zhCN', '放逐', '每次远征额外获得1次放逐机会。被放逐的选项在该次远征中不会再出现。'),
(7, 'zhCN', '第二次机会', '每次远征一次：致命伤害会改为使你以50%生命值复活。'),
(8, 'zhCN', '零钱', '远征开始时额外获得25勇气点数。'),
(9, 'zhCN', '向前看', '每次远征额外获得1次跳过机会。跳过时支付四分之一个宝箱价格的勇气点数。'),
(10, 'zhCN', '被动槽位', '远征中的被动槽位增加1个。'),
(11, 'zhCN', '法术槽位', '远征中的法术槽位增加1个。'),
(12, 'zhCN', '第二视觉', '进化选项允许你选择该法术的任意进化方向。'),
(13, 'zhCN', '神秘洞察', '远征中获得的经验值提高5%。'),
(14, 'zhCN', '预感', '进化可以提前1级出现。'),
(15, 'zhCN', '诅咒之地', '受到的治疗效果降低50%。金币提高20%。'),
(16, 'zhCN', '末日时钟', '楼层首领提前60秒到来。金币提高15%。'),
(17, 'zhCN', '强化的精英', '精英额外带有1个词缀。金币提高20%。'),
(18, 'zhCN', '叠好的牌堆', '暗月卡片禁用栏位增加1个。'),
(19, 'zhCN', '封印雕文', '雕文禁用栏位增加1个。'),
(20, 'zhCN', '威力', '+1%力量和+1%最大生命值。'),
(21, 'zhCN', '洞察', '远征中获得的经验值+2%。'),
(22, 'zhCN', '财运', '远征中获得的金币和废料+3%。');
DELETE FROM `bonk_tier_locale` WHERE `locale` = 'zhCN';
INSERT INTO `bonk_tier_locale` (`id`, `locale`, `name`, `description`, `details`) VALUES
(1, 'zhCN', '普通', '在开阔的地带挑战一层。击败该层首领即可赢得远征。', '首领的法术略有预判。^精英带有1个词缀。'),
(2, 'zhCN', '史诗', '逐层攀升，迎战最致命的强敌。每一层都更加艰难，回报也更丰厚；过了第20层，攀升仍将继续。获得的专精经验值提高100%。', '敌人的生命值提高220%，造成的伤害提高60%，且每层还会继续提高。^施法者的射击会精确预判。^首领的法术会精确预判，并获得更多攻击手段。^25%的敌人是老兵：更强悍，奖励也更高。^精英带有3个词缀。冲锋者冲锋更频繁。'),
(3, 'zhCN', '英雄', '在更凶险的地带挑战两层，敌人更强，战利品更好，暗月奖券更多，专精经验值提高50%。', '敌人的生命值提高60%，造成的伤害提高30%。^施法者的射击预判更准一些。^首领的法术预判更多，并获得额外的攻击手段。^15%的敌人是老兵：更强悍，奖励也更高。^精英带有2个词缀。冲锋者冲锋更频繁。');
