INSERT INTO `bonk_upgrade_locale` (`id`, `locale`, `name`, `description`) VALUES
(5, 'zhCN', '健步如飞', '移动速度提高2%。'),
(6, 'zhCN', '贪婪', '金币提高5%。'),
(14, 'zhCN', '拾取范围', '拾取范围提高10%。'),
(15, 'zhCN', '幸运', '幸运提高3点。'),
(16, 'zhCN', '冲刺距离', '冲刺距离提高0.8码。'),
(17, 'zhCN', '冲刺冷却', '冲刺冷却时间缩短0.6秒。'),
(18, 'zhCN', '二段冲刺', '冲刺充能次数增加1次。'),
(19, 'zhCN', '讨价还价', '开箱和购买商人物品消耗的勇气点数降低4%。'),
(20, 'zhCN', '废料回收', '拆解装备获得的勇气点数提高10%。'),
(21, 'zhCN', '卡牌高手', '宝箱额外提供1张暗月卡片。'),
(22, 'zhCN', '明晰', '升级时额外提供1个选项。'),
(23, 'zhCN', '赏金猎人', '限时事件（如财宝地精和赏金）的时间延长2秒。'),
(24, 'zhCN', '调谐', '魔网占领速度提高8%，月亮井持续时间提高8%。'),
(25, 'zhCN', '炉石学识', '炉石的出现几率提高20%。站入其法环所需的时间缩短1秒。'),
(26, 'zhCN', '领先起跑', '远征开始时等级提高1级，并获得对应的升级选项。'),
(27, 'zhCN', '幸运抽牌', '远征开始时随机获得一张普通品质的暗月卡片（等级2时为优秀品质）。'),
(28, 'zhCN', '驮兽', '提取保险库的容量增加1格。炉石的保险库仍只有1格。'),
(30, 'zhCN', '预知', '每次远征开始时可额外选择一个雕文。'),
(31, 'zhCN', '补货', '吉克希尔每次造访时可以多补货1次。'),
(40, 'zhCN', '力量', '力量提高3%。'),
(41, 'zhCN', '迅捷', '急速提高2.5%。'),
(42, 'zhCN', '精确', '致命一击几率提高1.2%。'),
(43, 'zhCN', '坚韧', '最大生命值提高4%。'),
(44, 'zhCN', '坚韧', '护甲提高1.5点。'),
(45, 'zhCN', '敏捷', '闪避几率提高0.8%。'),
(46, 'zhCN', '无情', '致命一击伤害提高4%。'),
(47, 'zhCN', '范围', '范围提高2.5%。');
